// newInput builds the insert a Batch queues for in under parent, and
// the record it stands for, named: the same resolution Create applies.
func (r *GraphQLReservationRepository) newInput(parent string, in *reservationv1.Reservation) (resourceql.CreateInput, *reservationv1.Reservation, error) {
	var ci resourceql.CreateInput
	parentIDs, err := repox.SplitName(parent, "hotels")
	if err != nil {
		return ci, nil, err
	}
	id := repox.NewULID()
	rowID := id
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "hotels", "reservations")
		if err != nil {
			return ci, nil, err
		}
		for i := range parentIDs {
			if ids[i] != parentIDs[i] {
				return ci, nil, fmt.Errorf("%w: name %q is not under parent %q", repox.ErrInvalidArgument, in.GetName(), parent)
			}
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*reservationv1.Reservation)
	in.Name = FormatReservationName(parentIDs[0], id)
	id = rowID // keyed as Create keys it
	ci = reservationToCreateInput(in)
	ci.Id = id
	ci.HotelId = parentIDs[0]
	ci.Etag = repox.NewULID()
	now := tsToStr(timestamppb.New(time.Now().UTC()))
	ci.CreateTime = now
	ci.UpdateTime = now
	return ci, in, nil
}

